import {it,expect,vi} from 'vitest'
import {LiveSession} from './live-session'
import {liveFixture,liveTracks} from './live-fixture'
import {returnFixture} from './return-fixture'
import {continuationPosition} from './live-contract'
function setup(){const approval=liveFixture(),[a,b]=Object.values(liveTracks(approval)),ctx={currentTime:10},source:any={track:a,at:0,offset:0,gain:{gain:{}},nodes:[]},state:any={source,position:10,playing:true,free:true},graph:any={exit:approval.scene.exits.at(-1),nextExit:()=>approval.scene.exits[0],setExit:vi.fn(),stop:vi.fn(),cancel:vi.fn()},prepared:any={approval,pcm:{},target:b,bodyBuffers:new Map(),release:vi.fn()},catalog:any={load:vi.fn(async()=>[]),candidates:vi.fn(()=>[{from:a.id,to:b.id,sourcePosition:40}]),prepare:vi.fn(async()=>prepared),dispose:vi.fn()}
 const port:any={ctx,active:()=>state.source,position:()=>state.position,playing:()=>state.playing,available:()=>state.free,tracks:()=>[a,b],notify:vi.fn(),log:vi.fn(),status:vi.fn(),locked:vi.fn(),schedule:vi.fn(()=>graph),createBody:vi.fn((_r:any,e:any,at:number)=>({track:b,at,offset:e.bPosition,stream:{pins:new Set(),deadline:Infinity,pump:vi.fn()}})),retire:vi.fn(),commit:vi.fn((deck:any)=>{state.source=deck}),protect:vi.fn(),detach:vi.fn(()=>vi.fn())}
 return{approval,a,b,ctx,state,port,catalog,prepared,graph,session:new LiveSession(port,catalog)}}
it('returns to native A at the slip position and records attachment, not B takeover',async()=>{
 const f=setup();f.prepared.approval=returnFixture();f.prepared.target=f.a;f.port.createBody.mockImplementation((r:any,e:any,at:number)=>({track:r.target,at,offset:continuationPosition(r.approval,e),stream:{pins:new Set(),pump:vi.fn()}}));const session=new LiveSession(f.port,f.catalog,'return-a');session.setEnabled(true);await session.warm([f.b.id]);f.ctx.currentTime=35;f.state.position=35;expect(session.arm()).toBe(true);expect(session.pending?.plan).toMatchObject({to:f.a.id,entry:70});expect(session.pending?.attachedTrackId).toBe(f.b.id)
 f.ctx.currentTime=70.009;session.tick();expect(f.state.source.track.id).toBe(f.a.id);expect(f.state.source.offset).toBe(70);expect(session.returnRevision).toBe(1);expect(session.snapshot().attachments).toHaveLength(1);expect(f.port.log).toHaveBeenCalledWith('longmix_return_complete',expect.objectContaining({attached:f.b.id,aPosition:70}));session.tick();expect(session.returnRevision).toBe(1)
})
it('explicit stop begins a fresh attachment history and allows the approved scene in a new run',async()=>{
 const f=setup();f.prepared.approval=returnFixture();f.prepared.target=f.a;f.catalog.candidates.mockReturnValue([{id:f.prepared.approval.id,from:f.a.id,to:f.b.id,sourcePosition:40}]);f.port.createBody.mockImplementation((r:any,e:any,at:number)=>({track:r.target,at,offset:continuationPosition(r.approval,e),stream:{pins:new Set(),pump:vi.fn()}}));const session=new LiveSession(f.port,f.catalog,'return-a');session.setEnabled(true);await session.warm([f.b.id]);f.ctx.currentTime=35;f.state.position=35;session.arm();f.ctx.currentTime=70.009;session.tick();expect(session.candidateIds([f.b])).toEqual([]);session.stop();expect(session.candidateIds([f.b])).toEqual([f.b.id]);expect(session.snapshot().attachments).toEqual([])
})
it('a failed native commit retains cleanup ownership and emits no successful return',async()=>{
 const f=setup();f.session.setEnabled(true);await f.session.warm([f.b.id]);f.ctx.currentTime=35;f.state.position=35;f.session.arm();f.port.commit.mockImplementation(()=>{throw Error('commit changed')});f.ctx.currentTime=80.009;expect(()=>f.session.tick()).not.toThrow();expect(f.prepared.release).toHaveBeenCalled();expect(f.port.locked).toHaveBeenLastCalledWith(false);expect(f.port.log.mock.calls.some(([k]:any)=>k==='longmix_handoff_complete')).toBe(false)
})
it('prepares a future eligible scene without changing the active deck',async()=>{const f=setup();f.session.setEnabled(true);await f.session.warm([f.b.id]);expect(f.session.snapshot().state).toBe('ready');expect(f.session.upcoming?.approval.id).toBe(f.approval.id);expect(f.port.schedule).not.toHaveBeenCalled();expect(f.state.source.track.id).toBe(f.a.id)})
it('rejects stale preparation after source replacement and keeps ordinary playback untouched',async()=>{const f=setup();let done!:(x:any)=>void;f.catalog.prepare.mockImplementation(()=>new Promise(r=>done=r));f.session.setEnabled(true);const task=f.session.warm([f.b.id]);await vi.waitFor(()=>expect(done).toBeTypeOf('function'));f.state.source={...f.state.source};done(f.prepared);await task;expect(f.session.upcoming).toBeNull();expect(f.prepared.release).toHaveBeenCalled();expect(f.port.schedule).not.toHaveBeenCalled()})
it('maps live A source position to the same context and commits B without a finite audition stop',async()=>{const f=setup();f.session.setEnabled(true);await f.session.warm([f.b.id]);f.state.position=35;f.ctx.currentTime=35;expect(f.session.arm()).toBe(true);expect(f.session.pending?.start).toBe(40);f.ctx.currentTime=80.009;f.session.tick();expect(f.port.commit).toHaveBeenCalledTimes(1);expect(f.state.source.track.id).toBe(f.b.id);f.ctx.currentTime=110;f.session.tick();expect(f.state.source.track.id).toBe(f.b.id);expect(f.port.retire).not.toHaveBeenCalledWith(f.state.source)})
it('manual next selects a safe approved exit; disabling never interrupts an active scene',async()=>{const f=setup();f.session.setEnabled(true);await f.session.warm([f.b.id]);f.ctx.currentTime=35;f.state.position=35;f.session.arm();f.ctx.currentTime=45;f.session.setEnabled(false);expect(f.graph.setExit).toHaveBeenCalledWith(f.approval.scene.exits[0]);expect(f.session.pending?.end).toBe(60);expect(f.port.commit).not.toHaveBeenCalled();f.ctx.currentTime=60.009;f.session.tick();expect(f.port.commit).toHaveBeenCalledTimes(1)})
it('expired anchors and failed preparation leave the original player free to use its fallback',async()=>{const f=setup();f.session.setEnabled(true);await f.session.warm([f.b.id]);f.state.position=40;expect(f.session.arm()).toBe(false);expect(f.port.schedule).not.toHaveBeenCalled();f.state.position=10;f.catalog.prepare.mockRejectedValue(Error('下载失败'));await f.session.warm([f.b.id]);expect(f.session.snapshot().reason).toContain('下载失败');expect(f.state.source.track.id).toBe(f.a.id)})
it('stop releases every owned resource and prevents a delayed handoff',async()=>{const f=setup();f.session.setEnabled(true);await f.session.warm([f.b.id]);f.state.position=35;f.ctx.currentTime=35;f.session.arm();f.session.stop();f.ctx.currentTime=100;f.session.tick();expect(f.port.commit).not.toHaveBeenCalled();expect(f.prepared.release).toHaveBeenCalled();expect(f.graph.stop).toHaveBeenCalled()})
it('will not arm a second scene while a normal handoff owns the decks',async()=>{const f=setup();f.session.setEnabled(true);await f.session.warm([f.b.id]);f.state.free=false;expect(f.session.arm()).toBe(false);expect(f.port.schedule).not.toHaveBeenCalled()})
it('cancellation of a pending warmup releases a late result without reinstalling the same source scene',async()=>{const f=setup();let done!:(x:any)=>void;f.catalog.prepare.mockImplementation(()=>new Promise(r=>done=r));f.session.setEnabled(true);const task=f.session.warm([f.b.id]);await vi.waitFor(()=>expect(done).toBeTypeOf('function'));f.session.cancelPreparation();done(f.prepared);await task;expect(f.session.upcoming).toBeNull();expect(f.prepared.release).toHaveBeenCalled();expect(f.port.schedule).not.toHaveBeenCalled()})

it('reports actual replacement source count and approval independently of additive layers',async()=>{
 const f=setup();f.prepared.roles={approval:{id:'role-id',mode:'roles-cd',sources:{c:{},d:{}}},buffers:new Map(),release:vi.fn()};f.session.setEnabled(true);await f.session.warm([f.b.id]);expect(f.session.snapshot()).toMatchObject({sourceCount:4,roleId:'role-id',replacementMode:'roles-cd'});f.ctx.currentTime=35;f.state.position=35;expect(f.session.arm()).toBe(true);expect(f.port.log).toHaveBeenCalledWith('longmix_scene_scheduled',expect.objectContaining({sourceCount:4,roleApproval:f.prepared.roles.approval}))
})

it('shares in-flight catalog preparation with normal playback warmup',async()=>{
 const f=setup()
 let finish!:()=>void
 f.catalog.load.mockImplementation(()=>new Promise<void>(resolve=>finish=resolve))
 f.session.setEnabled(true)
 const load=f.session.initialize(),warm=f.session.warm([f.b.id])
 expect(f.catalog.load).toHaveBeenCalledTimes(1)
 finish()
 await Promise.all([load,warm])
 expect(f.session.upcoming?.approval.id).toBe(f.approval.id)
})
